  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=9$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$9$", "$-9$", "$10$", "$8$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = 9$.', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-1 & 2\\ -1 & 3\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$-3$", "$-1$", "$3$", "$-4$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=3$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 3/-1 = -3$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & -5\\ 0 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-1 & 6\\ 1 & -5\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$5$", "$7$", "$-5$", "$4$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-5$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -5/-1 = 5$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-5 & -1\\ 6 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 0\\ 1 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 0\\ 6 & -1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -1/-1 = 1$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 5\\ -1 & -6\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$6$", "$8$", "$-6$", "$5$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-6$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -6/-1 = 6$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 1\\ -3 & -4\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$4$", "$6$", "$-4$", "$3$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-4$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -4/-1 = 4$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & -5\\ 1 & 3\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$-3$", "$-1$", "$3$", "$-4$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=3$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 3/-1 = -3$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}5 & -2\\ 2 & -1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -1/-1 = 1$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}4 & 3\\ -1 & -1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -1/-1 = 1$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}0 & 1\\ 1 & -4\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$4$", "$6$", "$-4$", "$3$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-4$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -4/-1 = 4$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 1\\ 0 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & 0 & -1\\ 1 & 1 & 1\\ -2 & 3 & 1\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$4$", "$7$", "$-4$", "$2$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 4$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}3 & -4 & 3\\ -2 & 1 & -4\\ 2 & -2 & 3\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-3$", "$0$", "$3$", "$-5$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -3$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}0 & -4 & -1\\ 1 & -2 & -1\\ -4 & 3 & 3\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-4$", "$-1$", "$4$", "$-6$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -4$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-1 & -3 & 3\\ -4 & 3 & -1\\ 3 & 1 & -2\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$7$", "$10$", "$-7$", "$5$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 7$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}2 & 2 & 1\\ 1 & -1 & -2\\ 2 & 3 & 2\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$2$", "$5$", "$-2$", "$0$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 2$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}2 & 1 & 4\\ 1 & 1 & 1\\ 1 & 1 & 2\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$0$", "$3$", "$6$", "$-2$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 0$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}2 & 3 & -3\\ -1 & -1 & 1\\ 0 & -1 & 0\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$0$", "$3$", "$6$", "$-2$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 0$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & 0 & -3\\ 1 & -4 & 4\\ 4 & 3 & 4\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-4$", "$-1$", "$4$", "$-6$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -4$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & -1 & 1\\ 0 & 2 & -1\\ 3 & -2 & 0\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-3$", "$0$", "$3$", "$-5$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -3$.', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}0 & 1 & -4\\ -1 & -1 & 3\\ -2 & 0 & -1\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-8$", "$-5$", "$8$", "$-10$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -8$.', 'Inverse of a Matrix', false, 'second', 2),
