  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Apply one Newton-Raphson step $x_2 = x_1 - f(x_1)/f''(x_1)$ to $f(x) = x^{2} - 33$ with $x_1 = 6$. Find $x_2$.', '["$23/4$", "$27/4$", "$19/4$", "$6$"]'::jsonb, 0, '$f(x_1) = 3$ and $f''(x_1) = 12$, so $x_2 = 6 - \dfrac{3}{12} = 23/4$.', 'Newton-Raphson Method', false, 'second', 2),
