  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A linear programming constraint reads $3x - 2y \leq 12$. Which of the following is an equivalent way to write this same constraint?', '["$-3x + 2y \\geq -12$", "$3x - 2y \\geq 12$", "$-3x - 2y \\leq 12$", "$2x - 3y \\leq 12$"]'::jsonb, 0, 'Multiplying both sides of $3x-2y\leq12$ by $-1$ reverses the inequality direction, giving $-3x+2y\geq-12$ -- an equivalent constraint.', 'LP Formulation', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In a linear program, why is the non-negativity restriction $x_j \geq 0$ typically imposed on decision variables representing physical quantities (e.g. units produced, hours worked)?', '["Because negative amounts of a physical quantity (negative production, negative hours) have no real-world meaning", "Because the Simplex method cannot run without it, for purely computational reasons", "Because it guarantees the objective function is always positive", "Because it is required by the definition of an equation"]'::jsonb, 0, 'Decision variables in practical LP models usually represent real quantities that cannot be negative (you cannot produce -5 units), so $x_j\geq0$ reflects a real-world constraint, not just a mathematical convenience.', 'LP Formulation', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A factory problem has two products with production limits $x_1 \leq 40$ and $x_2 \leq 60$, plus a shared resource constraint $2x_1 + x_2 \leq 100$. Which point satisfies ALL three constraints (together with $x_1,x_2\geq0$)?', '["$(30, 30)$", "$(45, 10)$", "$(20, 70)$", "$(40, 60)$"]'::jsonb, 0, '$(30,30)$: $30\leq40$ ok, $30\leq60$ ok, $2(30)+30=90\leq100$ ok. $(45,10)$ fails $x_1\leq40$; $(20,70)$ fails $x_2\leq60$; $(40,60)$ fails $2(40)+60=140\leq100$.', 'LP Formulation', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following is NOT one of the standard components of a linear programming model?', '["A recursive function definition", "A linear objective function to maximize or minimize", "A set of linear constraints", "Non-negativity restrictions on the variables"]'::jsonb, 0, 'An LP model consists of a linear objective function, a set of linear constraints, and non-negativity restrictions -- a recursive function definition belongs to programming/algorithms, not to the LP formulation itself.', 'LP Formulation', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using the method of Lagrange multipliers, maximize $xy$ subject to $x+y=6$. What is the optimal value and where does it occur?', '["$9$ at $(x,y)=(3, 3)$", "$11$ at $(x,y)=(3, 3)$", "$7$ at $(x,y)=(0,0)$", "$6$ at $(x,y)=(0,0)$"]'::jsonb, 0, 'Setting $\nabla f = \lambda \nabla g$ together with the constraint and solving gives the critical point(s) (3,3), with the optimal value $9$ at $(3,3)$.', 'Lagrange Method', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using the method of Lagrange multipliers, minimize $x^2+y^2$ subject to $x+y=10$. What is the optimal value and where does it occur?', '["$50$ at $(x,y)=(5, 5)$", "$52$ at $(x,y)=(5, 5)$", "$48$ at $(x,y)=(0,0)$", "$47$ at $(x,y)=(0,0)$"]'::jsonb, 0, 'Setting $\nabla f = \lambda \nabla g$ together with the constraint and solving gives the critical point(s) (5,5), with the optimal value $50$ at $(5,5)$.', 'Lagrange Method', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using the method of Lagrange multipliers, maximize $x+2y$ subject to $x^2+y^2=5$. What is the optimal value and where does it occur?', '["$5$ at $(x,y)=(1, 2)$", "$-5$ at $(x,y)=(-1, -2)$", "$7$ at $(x,y)=(1, 2)$", "$2$ at $(x,y)=(0,0)$"]'::jsonb, 0, 'Setting $\nabla f = \lambda \nabla g$ together with the constraint and solving gives the critical point(s) (-1,-2), (1,2), with the optimal value $5$ at $(1,2)$.', 'Lagrange Method', false, 'second', 2),
